// Pseudo Cloud Function outline
exports.validateAndRedact = (event, context) => {
  const lines = readLinesFromGCS(event);
  lines.forEach(l => {
    if (validate(l)) {
      const redacted = redactPII(l);
      writeToGCS(redacted);
    }
  });
}
```

## Follow-up Questions

